import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, enCamino, Chip, Contador, Recorrido, Ondas, Destello, golpe, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const ORD = en('órdenes'), SENAL = en('señal'), NERV = en('nervios'), MOVERSE = en('moverse'), COR2 = en('corazón', 2), NO = en('no');
const MARC = en('marcapasos'), CELU = en('células'), NODO = en('nodo'), CARGAN = en('cargan'), FLASH = en('flash'), TOPE = en('tope');
const CHISPA = en('chispa'), CHISPA2 = en('chispa', 2), CORRE = en('corre'), OLA = en('ola'), APRIETA = en('aprieta'), ABAJO = en('abajo');
const RECARGAN = en('recargan'), SETENTA = en('setenta'), MINUTO = en('minuto'), CER2 = en('cerebro', 2), RAPIDO = en('rápido'), DESPACIO = en('despacio');
const TRASP = en('trasplantan'), NERVIO = en('nervio'), CONECT = en('conectado'), PECHO = en('pecho'), EMPIEZA = en('empieza'), LATIR = en('latir'), CUENTA = en('cuenta');
const NACIERAS = en('nacieras'), CHISPITA = en('chispita'), PARADO = en('parado'), MIENTRAS = en('Mientras'), SESENTA = en('sesenta'), DISPARO = en('disparó');
const DALE = en('Dale'), CABEZA = en('cabeza'), RAZON = en('razón');

const LIMA = '#E7FF00', VINO = '#8E1E2E', ROSA = '#D2475A', LILA = '#C9A0DC', PIEL = '#E3AE88';

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>{children}</svg>;

// latido doble: ph = fase (1 = un latido)
const lat = (ph: number) => {
  const p = ((ph % 1) + 1) % 1;
  return Math.exp(-p * 9) * 0.8 + Math.exp(-Math.abs(p - 0.3) * 16) * 0.35;
};
// el latido acelera en "rápido" y se frena en "despacio" (fase continua)
const fase = (s: number) => {
  const a = Math.min(s, RAPIDO), b = Math.max(0, Math.min(s, DESPACIO) - RAPIDO), c = Math.max(0, s - DESPACIO);
  return 1.25 * a + 1.9 * b + 0.8 * c;
};

const HEART = 'M 0 150 C -200 30 -200 -110 -90 -135 C -40 -145 -5 -120 0 -95 C 8 -125 50 -150 105 -135 C 205 -105 200 30 0 150 Z';

// Protagonista de fondo: el corazón rojo vino con venas azules
const Corazon: React.FC<{x: number; y: number; sc?: number; b?: number; chispa?: number; op?: number}> = ({x, y, sc = 1, b = 0, chispa = 0, op = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${sc * (1 + 0.075 * b)})`} opacity={op}>
    <defs>
      <radialGradient id="hG" cx="38%" cy="30%" r="80%"><stop offset="0%" stopColor={ROSA} /><stop offset="55%" stopColor={VINO} /><stop offset="100%" stopColor="#47101A" /></radialGradient>
    </defs>
    <ellipse cx={0} cy={175} rx={150} ry={26} fill="rgba(0,0,0,0.35)" />
    <path d="M -22 -112 C -34 -205 20 -250 72 -222" stroke="#9A2A3A" strokeWidth={48} fill="none" strokeLinecap="round" />
    <path d="M -88 -112 C -130 -176 -134 -232 -104 -274" stroke="#3F6FB5" strokeWidth={38} fill="none" strokeLinecap="round" />
    <path d={HEART} fill="url(#hG)" stroke="#47101A" strokeWidth={6} />
    <path d="M -72 -62 C -104 0 -84 62 -28 106" stroke="#3F6FB5" strokeWidth={8} fill="none" strokeLinecap="round" opacity={0.9} />
    <path d="M 70 -80 C 110 -20 90 50 40 100" stroke="#3F6FB5" strokeWidth={7} fill="none" strokeLinecap="round" opacity={0.8} />
    <path d="M -30 -80 C -10 -20 20 20 10 90" stroke="#C0394B" strokeWidth={6} fill="none" strokeLinecap="round" opacity={0.8} />
    <ellipse cx={-74} cy={-66} rx={20} ry={46} fill="#fff" opacity={0.32} transform="rotate(24 -74 -66)" />
    {chispa > 0 && (
      <g transform={`translate(-84 -108) scale(${chispa})`}>
        <circle r={46} fill={LIMA} opacity={0.35} />
        <circle r={18} fill={LIMA} />
      </g>
    )}
  </g>
);

// cerebro rosado lila con pliegues
const Cerebro: React.FC<{x: number; y: number; sc?: number; sy?: number; ang?: number}> = ({x, y, sc = 1, sy = 1, ang = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc} ${sc * sy})`}>
    <defs>
      <radialGradient id="cbG" cx="40%" cy="30%" r="80%"><stop offset="0%" stopColor="#E4C6F0" /><stop offset="60%" stopColor={LILA} /><stop offset="100%" stopColor="#8D66A4" /></radialGradient>
    </defs>
    <path d="M -130 20 C -170 -50 -110 -120 -30 -110 C 0 -140 70 -130 100 -100 C 170 -90 180 -10 140 30 C 150 80 80 100 40 80 C 10 110 -60 110 -80 70 C -110 80 -140 60 -130 20 Z" fill="url(#cbG)" stroke="#7A5290" strokeWidth={5} />
    {[[-90, -20, -30, -60], [-60, 40, 10, 10], [10, -70, 70, -40], [40, 30, 110, 10], [-30, -30, 30, -10]].map(([a, b, c, d], i) => (
      <path key={i} d={`M ${a} ${b} C ${a + 25} ${b - 40} ${c - 20} ${d + 30} ${c} ${d}`} stroke="#8D66A4" strokeWidth={7} fill="none" strokeLinecap="round" opacity={0.8} />
    ))}
    <ellipse cx={-60} cy={-60} rx={34} ry={14} fill="#fff" opacity={0.35} />
  </g>
);

const Megafono: React.FC<{x: number; y: number; ang: number; op?: number}> = ({x, y, ang, op = 1}) => (
  <g transform={`translate(${x} ${y}) rotate(${ang})`} opacity={op}>
    <path d="M 0 -26 L 120 -80 L 120 80 L 0 26 Z" fill="#E8662A" stroke="#7A2E0E" strokeWidth={5} />
    <rect x={-40} y={-30} width={46} height={60} rx={12} fill="#555B66" stroke="#2B2F36" strokeWidth={5} />
    <path d="M 18 -20 L 100 -52" stroke="#fff" strokeWidth={8} opacity={0.5} strokeLinecap="round" />
    <rect x={-18} y={28} width={22} height={50} rx={8} fill="#3A3E47" />
  </g>
);

const Equis: React.FC<{x: number; y: number; t0: number; r?: number}> = ({x, y, t0, r = 70}) => {
  const {lin} = useS();
  const a = lin(t0, t0 + 0.18, 0, 1), b = lin(t0 + 0.16, t0 + 0.34, 0, 1);
  if (a <= 0) return null;
  return (
    <g>
      <line x1={x - r} y1={y - r} x2={x - r + 2 * r * a} y2={y - r + 2 * r * a} stroke={LIMA} strokeWidth={24} strokeLinecap="round" />
      <line x1={x + r} y1={y - r} x2={x + r - 2 * r * b} y2={y - r + 2 * r * b} stroke={LIMA} strokeWidth={24} strokeLinecap="round" />
    </g>
  );
};

const Fondo: React.FC<{base: string; linea: string; luz: string; tipo?: 'piel' | 'celulas' | 'fibra' | 'papel'; semilla?: number}> = ({base, linea, luz, tipo = 'celulas', semilla = 3}) => (
  <Textura tipo={tipo} base={base} linea={linea} luz={luz} semilla={semilla} />
);

// ---------- Sitio 1: corazón, cerebro con megáfono, brazo con nervios (E1-E2 y E12-E13) ----------
const NERVIOS: [number, number][] = [[470, 690], [400, 800], [290, 930], [250, 1060]];
const Inicio: React.FC<{fin?: boolean}> = ({fin}) => {
  const {s, lin} = useS();
  const ph = fin ? s * 1.25 : s * 1.25;
  const b = lat(ph);
  const brazoOn = !fin && s > NERV - 0.1;
  const flex = !fin ? lin(MOVERSE - 0.5, MOVERSE, 0, 1) * (1 - lin(MOVERSE + 0.8, MOVERSE + 1.4, 0, 1)) : 0;
  const cab = fin ? lin(CABEZA - 0.2, CABEZA + 0.5, 0, 1) : 0;
  const hombros = fin ? Math.max(0, golpe(s, CABEZA + 0.5, 14, 3)) : 0;
  const pulso = enCamino(s, NERVIOS, SENAL, NERV);
  const paradas = fin
    ? [{t: MIENTRAS - 0.2, x: 600, y: 1100, zoom: 1.35}, {t: DISPARO, x: 600, y: 1080, zoom: 1.5}, {t: DALE, x: 560, y: 960, zoom: 1.1}, {t: RAZON + 1, x: 560, y: 900, zoom: 1.0}]
    : [{t: 0, x: 600, y: 1120, zoom: 1.0}, {t: ORD, x: 600, y: 1060, zoom: 1.3}, {t: SENAL - 0.3, x: 520, y: 980, zoom: 1.1}, {t: NERV, x: 300, y: 1060, zoom: 1.35}, {t: MOVERSE + 0.6, x: 330, y: 1130, zoom: 1.3}, {t: COR2, x: 620, y: 1180, zoom: 1.25}, {t: MARC, x: 560, y: 1110, zoom: 1.5}];
  return (
    <AbsoluteFill style={{background: '#2A0B14'}}>
      <Camara paradas={paradas}>
        <Fondo base="radial-gradient(circle at 55% 62%, #6A2230, #36101B 70%, #1B0710)" linea="rgba(255,140,150,0.25)" luz="rgba(255,170,170,0.18)" tipo="piel" semilla={5} />
        <Brillo x={640} y={1230} r={520} color="rgba(210,71,90,0.45)" />
        <Lienzo>
          {/* cable cortado: línea del cerebro al corazón que no llega */}
          <path d="M 520 760 C 560 880 600 940 640 1000" stroke="#9AA3B2" strokeWidth={6} strokeDasharray="14 18" fill="none" opacity={0.7} />
          <circle cx={640} cy={1010} r={8} fill="#9AA3B2" />
          {s > NO && !fin && <Equis x={600} y={900} t0={NO} r={46} />}
          {/* cerebro con megáfono */}
          <Cerebro x={480} y={600} sc={1.15} sy={1 - 0.08 * hombros + 0.04 * Math.sin(s * 2)} ang={Math.sin(s * 1.5) * 2} />
          <Megafono x={300} y={640} ang={fin ? 20 + cab * 70 : 18 + Math.sin(s * 9) * (s < ORD ? 5 : 1)} />
          {!fin && Array.from({length: 3}).map((_, i) => <path key={i} d={`M ${390 + i * 26} ${690 + i * 30} q 18 24 40 20`} stroke="#fff" strokeWidth={5} strokeDasharray="4 12" fill="none" opacity={0.35 * Math.max(0, 1 - lin(ORD, ORD + 0.4, 0, 1))} strokeLinecap="round" />)}
          {!fin && <Equis x={300} y={650} t0={ORD} r={80} />}
          {/* nervios amarillos y brazo */}
          {!fin && (
            <g>
              <polyline points={NERVIOS.map((p) => p.join(',')).join(' ')} fill="none" stroke="#F2C230" strokeWidth={9} strokeLinecap="round" strokeLinejoin="round" opacity={s > SENAL - 0.5 ? 1 : 0.55} />
              <path d="M 250 1060 C 215 1150 215 1260 235 1340" stroke="#F2C230" strokeWidth={6} fill="none" opacity={0.8} />
              <g>
                <path d="M 226 1040 C 276 1030 300 1070 290 1130 L 262 1330 L 200 1330 L 196 1130 C 190 1080 200 1050 226 1040 Z" fill={PIEL} stroke="#9E6E4C" strokeWidth={5} />
                <g transform={`translate(231 1330) rotate(${-flex * 62})`}>
                  <path d="M -30 0 L 30 0 L 38 190 C 38 230 -38 230 -38 190 Z" fill={PIEL} stroke="#9E6E4C" strokeWidth={5} />
                  <ellipse cx={-4} cy={225} rx={44} ry={36} fill="#EDBE9C" stroke="#9E6E4C" strokeWidth={5} />
                </g>
                <ellipse cx={226} cy={1090} rx={16} ry={50} fill="#fff" opacity={0.25} />
              </g>
              {brazoOn && <circle cx={pulso.x} cy={pulso.y} r={20} fill="#FFF3B0" />}
              {s > SENAL && s < NERV + 0.1 && <circle cx={pulso.x} cy={pulso.y} r={44} fill="#F2C230" opacity={0.4} />}
            </g>
          )}
          <Corazon x={660} y={1260} sc={1.75} b={b} chispa={fin ? 0.6 + 0.4 * lat(s * 1.25 + 0.15) : 0} />
        </Lienzo>
        {fin && <Contador desde={0} hasta={60} t0={MIENTRAS + 0.2} t1={SESENTA + 0.1} x={540} y={470} sufijo=" latidos" size={80} color={LIMA} />}
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 2: dentro del corazón: nodo sinusal, carga, chispa y ola (E3-E6) ----------
const RUTA: [number, number][] = [[390, 640], [470, 820], [560, 1010], [600, 1220], [560, 1460]];
const Dentro: React.FC = () => {
  const {s, lin, spr} = useS();
  const carga = lin(CARGAN, TOPE, 0, 1, Easing.in(Easing.quad));
  const q = enCamino(s, RUTA, CORRE, ABAJO + 0.3);
  const atrios = lin(OLA, APRIETA, 0, 1) * (1 - lin(APRIETA + 0.4, APRIETA + 0.9, 0, 1));
  const vent = lin(APRIETA, APRIETA + 0.5, 0, 1) * (1 - lin(ABAJO + 0.4, ABAJO + 1.0, 0, 1));
  const flash = lin(FLASH, FLASH + 0.1, 0, 1) * (1 - lin(FLASH + 0.1, FLASH + 0.4, 0, 1));
  const paradas = [
    {t: MARC, x: 470, y: 760, zoom: 1.9}, {t: CELU, x: 400, y: 660, zoom: 2.2}, {t: NODO, x: 470, y: 800, zoom: 1.5}, {t: CARGAN, x: 540, y: 1000, zoom: 1.2},
    {t: TOPE, x: 540, y: 1000, zoom: 1.35}, {t: CHISPA, x: 420, y: 700, zoom: 1.8}, ...seguir(RUTA, CORRE, ABAJO + 0.3, 1.5, 6), {t: RECARGAN + 0.4, x: 560, y: 1100, zoom: 1.2},
  ];
  return (
    <AbsoluteFill style={{background: '#240810'}}>
      <Camara paradas={paradas}>
        <Fondo base="radial-gradient(circle at 50% 45%, #B8404F, #7A1D2B 60%, #2A0A12)" linea="rgba(60,10,20,0.6)" luz="rgba(255,150,150,0.2)" tipo="celulas" semilla={9} />
        <Brillo x={400} y={680} r={420} color="rgba(231,255,0,0.28)" t0={MARC} />
        <Lienzo>
          <defs>
            <radialGradient id="camG" cx="50%" cy="40%" r="70%"><stop offset="0%" stopColor="#7A1624" /><stop offset="100%" stopColor="#3C0A14" /></radialGradient>
            <radialGradient id="celG" cx="35%" cy="30%" r="70%"><stop offset="0%" stopColor="#F6FFA0" /><stop offset="60%" stopColor={LIMA} /><stop offset="100%" stopColor="#8FA800" /></radialGradient>
          </defs>
          {/* cuatro cámaras: aurículas arriba, ventrículos abajo */}
          <g>
            <ellipse cx={420} cy={800} rx={190 - 40 * atrios} ry={200 - 60 * atrios} fill="url(#camG)" stroke="#B8505E" strokeWidth={12} />
            <ellipse cx={700} cy={840} rx={170 - 36 * atrios} ry={190 - 56 * atrios} fill="url(#camG)" stroke="#B8505E" strokeWidth={12} />
            <ellipse cx={420} cy={1280} rx={200 - 50 * vent} ry={250 - 80 * vent} fill="url(#camG)" stroke="#B8505E" strokeWidth={12} />
            <ellipse cx={700} cy={1300} rx={190 - 44 * vent} ry={240 - 76 * vent} fill="url(#camG)" stroke="#B8505E" strokeWidth={12} />
            {[0, 1, 2].map((i) => <path key={i} d={`M ${300 + i * 140} ${600 + i * 20} q 20 50 0 100`} stroke="#E88A94" strokeWidth={4} fill="none" opacity={0.45} />)}
          </g>
          {/* racimo de células del nodo sinusal */}
          {Array.from({length: 9}).map((_, i) => {
            const cx = 345 + (i % 3) * 52 + h(i) * 16, cy = 600 + Math.floor(i / 3) * 48 + h(i + 4) * 12;
            const e = spr(MARC + 0.2 + i * 0.05, 12, 140);
            return <circle key={i} cx={cx} cy={cy} r={(22 + h(i * 3) * 6) * e * (1 + 0.1 * carga + 0.2 * flash)} fill="url(#celG)" stroke="#7A8F00" strokeWidth={3} opacity={0.6 + 0.4 * carga} />;
          })}
          {/* chispa que corre y deja una ola de luz */}
          {s > CHISPA - 0.05 && s < RECARGAN + 0.6 && <Recorrido puntos={RUTA} t0={CORRE} t1={ABAJO + 0.3} color="rgba(231,255,0,0.9)" render={(x, y) => <g><circle cx={x} cy={y} r={70} fill={LIMA} opacity={0.3} /><circle cx={x} cy={y} r={24} fill={LIMA} /><circle cx={x} cy={y} r={10} fill="#fff" /></g>} />}
          {s > CORRE && s < ABAJO + 1.2 && <circle cx={q.x} cy={q.y} r={80 + 180 * lin(CORRE, ABAJO + 0.6, 0, 1)} fill="none" stroke="rgba(231,255,0,0.5)" strokeWidth={12} opacity={1 - lin(ABAJO, ABAJO + 1.2, 0, 1)} />}
          {s > CHISPA && s < CORRE && <circle cx={390} cy={640} r={30 + 10 * Math.sin(s * 30)} fill={LIMA} />}
        </Lienzo>
        {/* barra de batería de carga + flash de cámara antigua */}
        {s > CARGAN - 0.3 && s < CHISPA + 0.6 && (
          <div style={{position: 'absolute', left: 130, top: 1360, width: 360, height: 120, borderRadius: 24, border: '8px solid #E7FF00', background: 'rgba(10,10,10,0.7)', transform: `scale(${spr(CARGAN - 0.3, 12, 160)})`}}>
            <div style={{position: 'absolute', left: 8, top: 8, bottom: 8, width: 336 * carga, borderRadius: 14, background: 'linear-gradient(90deg, #C8E000, #F6FF70)'}} />
            <div style={{position: 'absolute', right: -24, top: 36, width: 16, height: 48, borderRadius: 6, background: LIMA}} />
          </div>
        )}
        {s > CARGAN - 0.3 && s < CHISPA + 0.6 && (
          <div style={{position: 'absolute', left: 620, top: 1330, width: 260, height: 170, transform: `scale(${spr(CARGAN, 12, 160)})`}}>
            <div style={{position: 'absolute', inset: '30px 0 0 0', borderRadius: 18, background: 'linear-gradient(180deg, #3A3A40, #16161A)', border: '5px solid #777'}} />
            <div style={{position: 'absolute', left: 90, top: 66, width: 80, height: 80, borderRadius: 80, background: 'radial-gradient(circle at 35% 30%, #7C9DBF, #14202E)', border: '6px solid #999'}} />
            <div style={{position: 'absolute', left: 190, top: 40, width: 46, height: 28, borderRadius: 6, background: `rgba(255,255,255,${0.35 + 0.65 * carga})`, boxShadow: `0 0 ${30 * carga}px #fff`}} />
            <div style={{position: 'absolute', left: 30, top: 8, width: 36, height: 30, background: '#999', borderRadius: 6}} />
          </div>
        )}
        <Chip texto="nodo sinusal" x={560} y={540} t0={NODO} t1={CARGAN + 0.4} size={64} />
        <Ondas x={390} y={640} t0={CHISPA} color={LIMA} radio={360} />
        <Destello t0={FLASH} fuerza={0.35 * (1 + flash)} />
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 3: el corazón entero latiendo con el contador (E7) ----------
const Entero: React.FC = () => {
  const {s} = useS();
  const b = lat(s * 1.2);
  return (
    <AbsoluteFill style={{background: '#240810'}}>
      <Camara paradas={[{t: RECARGAN, x: 540, y: 1000, zoom: 1.0}, {t: SETENTA, x: 540, y: 980, zoom: 1.12}, {t: MINUTO + 1.4, x: 540, y: 960, zoom: 1.25}]}>
        <Fondo base="radial-gradient(circle at 50% 50%, #5C1826, #2B0A13 70%, #12060A)" linea="rgba(255,120,130,0.2)" luz="rgba(255,150,150,0.15)" tipo="fibra" semilla={11} />
        <Brillo x={540} y={1050} r={600} color="rgba(210,71,90,0.45)" />
        <Lienzo>
          <Corazon x={540} y={1090} sc={2.2} b={b} chispa={0.7 + 0.3 * lat(s * 1.2 + 0.1)} />
        </Lienzo>
        <Contador desde={0} hasta={70} t0={SETENTA - 0.3} t1={MINUTO + 0.2} x={540} y={560} sufijo=" por minuto" size={72} color={LIMA} />
        <Ondas x={540} y={1050} t0={SETENTA} color="#FFB3BC" radio={560} />
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 4: el cerebro con dos perillas (E8) ----------
const Perilla: React.FC<{x: number; y: number; ang: number; txt: string}> = ({x, y, ang, txt}) => (
  <g transform={`translate(${x} ${y})`}>
    <circle r={92} fill="#2E3340" stroke="#8A93A6" strokeWidth={8} />
    <circle r={70} fill="#4A5266" />
    <g transform={`rotate(${ang})`}><rect x={-7} y={-64} width={14} height={50} rx={7} fill={LIMA} /><circle cy={-30} r={5} fill="#fff" /></g>
    <ellipse cx={-26} cy={-34} rx={22} ry={10} fill="#fff" opacity={0.25} />
    <text x={0} y={150} textAnchor="middle" fontFamily="Poppins, Arial, sans-serif" fontWeight={800} fontSize={42} fill="#fff">{txt}</text>
  </g>
);
const Cerebro4: React.FC = () => {
  const {s, lin} = useS();
  const a1 = -50 + 150 * lin(RAPIDO - 0.2, RAPIDO + 0.5, 0, 1, Easing.out(Easing.back(2)));
  const a2 = -50 - 20 + 100 * lin(DESPACIO - 0.2, DESPACIO + 0.5, 0, 1, Easing.out(Easing.back(2))) - 50;
  const b = lat(fase(s));
  return (
    <AbsoluteFill style={{background: '#20122A'}}>
      <Camara paradas={[{t: CER2 - 0.4, x: 540, y: 780, zoom: 1.3}, {t: RAPIDO - 0.2, x: 540, y: 1000, zoom: 1.0}, {t: DESPACIO + 0.4, x: 540, y: 1050, zoom: 1.12}, {t: DESPACIO + 2.2, x: 540, y: 900, zoom: 1.05}]}>
        <Fondo base="radial-gradient(circle at 50% 35%, #5B3B78, #2A1A3A 70%, #120A1A)" linea="rgba(231,200,255,0.2)" luz="rgba(220,180,255,0.18)" tipo="fibra" semilla={14} />
        <Brillo x={540} y={620} r={500} color="rgba(201,160,220,0.5)" />
        <Lienzo>
          <Cerebro x={540} y={620} sc={2.1} sy={1 + 0.03 * Math.sin(s * 2)} />
          <path d="M 540 780 L 540 940" stroke={LIMA} strokeWidth={6} strokeDasharray="10 14" opacity={0.7} />
          <Perilla x={340} y={1040} ang={a1} txt="acelerar" />
          <Perilla x={740} y={1040} ang={a2} txt="frenar" />
          <Corazon x={540} y={1450} sc={0.9} b={b} chispa={0.6} />
        </Lienzo>
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 5: la nevera de transporte con el corazón en hielo (E9) ----------
const Nevera: React.FC = () => {
  const {s, lin, spr} = useS();
